CUES = [(0.0, 1.46, 'Cuando tu perro mueve la cola,'), (1.51, 3.78, 'no siempre te está diciendo que\nestá contento.'), (4.37, 5.22, 'Fíjate en el lado.'), (5.9, 6.36, 'En 2007,'), (6.41, 10.01, 'un equipo italiano grabó a\nperros mirando cosas distintas.'), (10.51, 13.47, 'Al ver a su dueño, la cola se\niba más hacia la derecha.'), (14.02, 16.69, 'Al ver a un perro grande y\ndesconocido que le imponía,'), (16.74, 17.84, 'más hacia la izquierda.'), (18.42, 22.71, '¿Por qué? Cada mitad del cerebro\nmueve el lado contrario del\ncuerpo,'), (22.76, 25.39, 'y cada una lleva emociones\ndistintas: una,'), (25.44, 28.53, 'las ganas de acercarse; la otra,\nlas de alejarse.'), (29.05, 31.85, 'Y lo más loco: los otros perros\nlo leen.'), (32.39, 35.36, 'En 2013 les pusieron vídeos de\nperros moviendo la cola.'), (35.41, 37.0, 'Cuando iba hacia la izquierda,'), (37.05, 40.4, 'al que miraba se le aceleraba el\ncorazón y se ponía en alerta.'), (40.89, 42.93, 'Y no es solo el lado: una cola\nalta,'), (42.98, 45.71, 'rígida y que vibra muy rápido\npuede ser tensión,'), (45.76, 46.35, 'no alegría.'), (46.59, 50.23, 'En Canadá construyeron un perro\nrobot con cola.'), (50.8, 52.32, 'Con una cola larga moviéndose,'), (52.37, 54.26, 'los perros se le acercaban sin\nmiedo.'), (54.82, 56.6, 'Con una cola corta, dudaban más:'), (56.65, 58.89, 'no tenían claro qué les estaba\ndiciendo.'), (59.46, 65.01, '¿Y el tuyo? ¿Hacia qué lado\nmueve la cola cuando llegas a\ncasa? Fíjate esta noche y\ncuéntanoslo.'), (65.561, 67.061, '¿NO LO SABÍAS?'), (67.161, 68.661, 'El mundo tiene más historias.')]
